# Function to map NVQ levels to collapsed scheme
map_nvq_to_collapsed <- function(nvq_level) {
  case_when(
    nvq_level %in% c(4, 5) ~ 0,  # NVQ 4–5 equivalent
    nvq_level %in% c(1, 2, 3) ~ 1,  # NVQ 1–3 equivalent
    nvq_level == 0 ~ 2,  # Entry level or no qualifications
    nvq_level == 95 ~ 3,  # Other qualifications not mappable to the NVQ framework
    nvq_level == 96 ~ 4,  # None of these qualifications
    TRUE ~ NA_real_  # Missing values
  )
}

