library(labelled)
library(readr)

# Load datasets
wave1 <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t")
wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t")
ns8_main <- read_delim("data/input/ns8_2015_main_interview.tab", delim = "\t")
ns8_derived <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t")
ns9_main <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t")
ns9_derived <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t")

# Merge datasets by NSID
merged_data <- wave1 %>%
  full_join(wave4, by = "NSID") %>%
  full_join(ns8_main, by = "NSID") %>%
  full_join(ns8_derived, by = "NSID") %>%
  full_join(ns9_main, by = "NSID") %>%
  full_join(ns9_derived, by = "NSID")

# Function to map NVQ levels to collapsed scheme
map_nvq_to_collapsed <- function(nvq_level) {
  case_when(
    nvq_level %in% c(4, 5) ~ 0,  # NVQ 4–5 equivalent
    nvq_level %in% c(1, 2, 3) ~ 1,  # NVQ 1–3 equivalent
    nvq_level == 0 ~ 2,  # Entry level or no qualifications
    nvq_level == 95 ~ 3,  # Other qualifications not mappable to the NVQ framework
    nvq_level == 96 ~ 4,  # None of these qualifications
    TRUE ~ NA_real_  # Missing values
  )
}

# Derive educ25 (age 25)
# Create a simplified approach for vocational qualifications
vocational_vars <- c("W8VCQU0A", "W8VCQU0B", "W8VCQU0C", "W8VCQU0D", "W8VCQU0E", 
                     "W8VCQU0F", "W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J", 
                     "W8VCQU0K", "W8VCQU0L", "W8VCQU0M", "W8VCQU0N", "W8VCQU0O", 
                     "W8VCQU0P")

# Map each vocational qualification to NVQ level
vocational_nvq_map <- c(
  W8VCQU0A = 1, W8VCQU0B = 1, W8VCQU0C = 0, W8VCQU0D = 0,
  W8VCQU0E = 2, W8VCQU0F = 1, W8VCQU0G = 2, W8VCQU0H = 2,
  W8VCQU0I = 2, W8VCQU0J = 4, W8VCQU0K = 4, W8VCQU0L = 2,
  W8VCQU0M = 2, W8VCQU0N = 2, W8VCQU0O = 2, W8VCQU0P = 4
)

# Calculate highest vocational NVQ for each person
get_highest_voc_nvq <- function(row_data) {
  # Check non-substantive responses first
  if (!is.na(row_data$W8VCQU0Q) && row_data$W8VCQU0Q == 1) return(-8)
  if (!is.na(row_data$W8VCQU0R) && row_data$W8VCQU0R == 1) return(-9)

  # Get all vocational qualifications that are "Yes" (1)
  valid_levels <- sapply(vocational_vars, function(var) {
    if (!is.na(row_data[[var]]) && row_data[[var]] == 1) {
      return(vocational_nvq_map[var])
    }
    return(NA)
  })

  max_level <- max(valid_levels, na.rm = TRUE)
  if (!is.finite(max_level)) return(NA)
  return(max_level)
}

educ25 <- merged_data %>%
  mutate(
    academic_nvq = map_nvq_to_collapsed(W8DHANVQH),
    vocational_nvq = apply(select(., all_of(vocational_vars), W8VCQU0Q, W8VCQU0R), 1, get_highest_voc_nvq),
    educ25 = case_when(
      !is.na(academic_nvq) & !is.na(vocational_nvq) ~ pmax(academic_nvq, vocational_nvq, na.rm = TRUE),
      !is.na(academic_nvq) ~ academic_nvq,
      !is.na(vocational_nvq) ~ vocational_nvq,
      TRUE ~ -3
    )
  ) %>%
  select(NSID, educ25)

# Derive educ32 (age 32)
educ32 <- merged_data %>%
  mutate(
    educ32 = case_when(
      !is.na(W9DANVQH) & !is.na(W9DVNVQH) ~ pmax(W9DANVQH, W9DVNVQH, na.rm = TRUE),
      !is.na(W9DANVQH) ~ W9DANVQH,
      !is.na(W9DVNVQH) ~ W9DVNVQH,
      TRUE ~ -3
    )
  ) %>%
  select(NSID, educ32)

# Derive educadtl32 (detailed academic qualifications at age 32)
academic_vars <- paste0("W9ACQU", sprintf("%02d", 0:21))

get_academic_code <- function(row_data) {
  # Check non-substantive responses
  if (!is.na(row_data$W9ACQU0T) && row_data$W9ACQU0T == 1) return(-8)
  if (!is.na(row_data$W9ACQU0U) && row_data$W9ACQU0U == 1) return(-9)
  if (!is.na(row_data$W9ACQU0V) && row_data$W9ACQU0V == 1) return(-2)

  # Check if all substantive are "No" (2)
  substantive_vars <- academic_vars[!academic_vars %in% c("W9ACQU0S", "W9ACQU0T", "W9ACQU0U", "W9ACQU0V")]
  if (all(sapply(substantive_vars, function(var) !is.na(row_data[[var]]) && row_data[[var]] == 2))) {
    return(96)
  }

  # Find first "Yes" (1)
  for (i in seq_along(substantive_vars)) {
    if (!is.na(row_data[[substantive_vars[i]]]) && row_data[[substantive_vars[i]]] == 1) {
      return(i)
    }
  }

  return(-3)
}

educadtl32 <- merged_data %>%
  mutate(educadtl32 = apply(select(., all_of(academic_vars)), 1, get_academic_code)) %>%
  select(NSID, educadtl32)

# Derive educvdtl32 (detailed vocational qualifications at age 32)
vocational_vars_w9 <- paste0("W9VCQU", sprintf("%02d", 0:34))

get_vocational_code <- function(row_data) {
  # Check non-substantive responses
  if (!is.na(row_data$W9VCQUAH) && row_data$W9VCQUAH == 1) return(-8)
  if (!is.na(row_data$W9VCQUAI) && row_data$W9VCQUAI == 1) return(-9)

  # Check if all substantive are "No" (2)
  substantive_vars <- vocational_vars_w9[!vocational_vars_w9 %in% c("W9VCQUAG", "W9VCQUAH", "W9VCQUAI")]
  if (all(sapply(substantive_vars, function(var) !is.na(row_data[[var]]) && row_data[[var]] == 2))) {
    return(96)
  }

  # Find first "Yes" (1)
  for (i in seq_along(substantive_vars)) {
    if (!is.na(row_data[[substantive_vars[i]]]) && row_data[[substantive_vars[i]]] == 1) {
      return(i)
    }
  }

  return(-3)
}

educvdtl32 <- merged_data %>%
  mutate(educvdtl32 = apply(select(., all_of(vocational_vars_w9)), 1, get_vocational_code)) %>%
  select(NSID, educvdtl32)

# Combine all derived variables
final_data <- educ25 %>%
  full_join(educ32, by = "NSID") %>%
  full_join(educadtl32, by = "NSID") %>%
  full_join(educvdtl32, by = "NSID")

# Write output
write_csv(final_data, "data/output/cleaned_data.csv")"
  }
}

