  if (!is.na(data_row$W8VCQU0Q) && data_row$W8VCQU0Q == 1) return(-8)
  if (!is.na(data_row$W8VCQU0R) && data_row$W8VCQU0R == 1) return(-9)

  # Get all vocational qualifications that are "Yes" (1)
